package com.fintrack.controller; import com.fintrack.dto.BudgetRequest; import com.fintrack.model.*; import com.fintrack.repository.BudgetRepository; import com.fintrack.service.CurrentUser; import jakarta.validation.Valid; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/budgets") public class BudgetController{private final BudgetRepository repo;private final CurrentUser current;public BudgetController(BudgetRepository r,CurrentUser c){repo=r;current=c;}@GetMapping public List<Budget> all(Authentication a){return repo.findByUserId(current.get(a).getId());}@PostMapping public Budget add(@Valid @RequestBody BudgetRequest r,Authentication a){Budget b=new Budget();b.setUser(current.get(a));b.setCategory(r.category());b.setLimitAmount(r.limitAmount());return repo.save(b);}@PutMapping("/{id}")public Budget update(@PathVariable Long id,@Valid @RequestBody BudgetRequest r,Authentication a){Budget b=repo.findById(id).orElseThrow(()->new IllegalArgumentException("Budget not found"));if(!b.getUser().getId().equals(current.get(a).getId()))throw new IllegalArgumentException("Not your budget");b.setCategory(r.category());b.setLimitAmount(r.limitAmount());return repo.save(b);}@DeleteMapping("/{id}")public void delete(@PathVariable Long id,Authentication a){Budget b=repo.findById(id).orElseThrow(()->new IllegalArgumentException("Budget not found"));if(!b.getUser().getId().equals(current.get(a).getId()))throw new IllegalArgumentException("Not your budget");repo.delete(b);}}
